import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { refreshConfirmedDraftOrderShippingMethodsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await refreshConfirmedDraftOrderShippingMethodsWorkflow(
      req.scope)
    .run({
      input: {
        "order_id": "order_123"
      }
    })

  res.send(result)
}

